<?php declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/includes/auth.php';$db=db();$e=fn($v)=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');$tot=$db->query("SELECT COUNT(*) invoices,COALESCE(SUM(total),0) billed,COALESCE(SUM(amount_paid),0) paid,COALESCE(SUM(balance_due),0) outstanding FROM invoices WHERE status<>'cancelled'")->fetch();$over=(int)$db->query("SELECT COUNT(*) FROM invoices WHERE status='overdue' OR (balance_due>0 AND due_date<CURDATE() AND status NOT IN ('paid','cancelled'))")->fetchColumn();$paidMonth=(float)$db->query("SELECT COALESCE(SUM(amount),0) FROM invoice_payments WHERE status='successful' AND paid_at>=DATE_FORMAT(CURDATE(),'%Y-%m-01')")->fetchColumn();$rows=$db->query("SELECT i.*,COALESCE(c.name,l.name,'Unknown') client_name FROM invoices i LEFT JOIN clients c ON c.id=i.client_id LEFT JOIN leads l ON l.id=i.lead_id ORDER BY i.created_at DESC LIMIT 15")->fetchAll();function money9($v,$c){return $c.' '.number_format((float)$v,2);}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Financial Dashboard</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-5"><div class="d-flex justify-content-between mb-4"><div><h1 class="h2">Financial Dashboard</h1><p class="text-muted">Billing, collections and outstanding balances.</p></div><a class="btn btn-dark" href="invoice-form.php">+ Invoice</a></div><div class="row g-3 mb-4"><div class="col-md-3"><div class="card"><div class="card-body"><small>Invoices</small><div class="fs-3 fw-bold"><?=$e($tot['invoices'])?></div></div></div></div><div class="col-md-3"><div class="card"><div class="card-body"><small>Total Billed</small><div class="fs-5 fw-bold"><?=$e(money9($tot['billed'],'USD'))?></div></div></div></div><div class="col-md-3"><div class="card"><div class="card-body"><small>Collected This Month</small><div class="fs-5 fw-bold"><?=$e(money9($paidMonth,'USD'))?></div></div></div></div><div class="col-md-3"><div class="card"><div class="card-body"><small>Outstanding</small><div class="fs-5 fw-bold"><?=$e(money9($tot['outstanding'],'USD'))?></div><div class="small text-danger"><?=$over?> overdue</div></div></div></div></div><div class="card"><div class="table-responsive"><table class="table mb-0 align-middle"><thead><tr><th>Invoice</th><th>Client</th><th>Total</th><th>Paid</th><th>Balance</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$e($r['invoice_number'])?></td><td><?=$e($r['client_name'])?></td><td><?=$e(money9($r['total'],$r['currency']))?></td><td><?=$e(money9($r['amount_paid'],$r['currency']))?></td><td><?=$e(money9($r['balance_due'],$r['currency']))?></td><td><?=$e($r['status'])?></td><td><?php if((float)$r['balance_due']>0):?><a class="btn btn-sm btn-outline-dark" href="invoice-payment.php?id=<?=$r['id']?>">Payment</a><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div></main></body></html>